{
  "platform": "host",
  "provider": "Tool",
  "method": "listTools",
  "data": {
    "tools": [
      {
        "name": "read",
        "description": "Read one governed text file inside this member's admitted file root. Paths resolve against that root; escaping targets are refused.",
        "parameters": {
          "type": "object",
          "properties": {
            "file_path": {
              "type": "string",
              "description": "path relative to the governed root, or an absolute path inside it"
            },
            "offset": {
              "type": "number",
              "description": "The line number to start reading from. Only provide if the file is too large to read at once."
            },
            "limit": {
              "type": "number",
              "description": "The number of lines to read. Only provide if the file is too large to read at once. Defaults to 2000."
            }
          },
          "required": [
            "file_path"
          ]
        }
      },
      {
        "name": "write",
        "description": "Create or fully replace one governed UTF-8 text file inside this member's admitted file root. Paths resolve against that root; escaping targets are refused. Overwrites an existing file only when the target is a regular file.",
        "parameters": {
          "type": "object",
          "properties": {
            "file_path": {
              "type": "string",
              "description": "path relative to the governed root, or an absolute path inside it"
            },
            "content": {
              "type": "string",
              "description": "the full UTF-8 content to write (empty string clears the file)"
            }
          },
          "required": [
            "file_path",
            "content"
          ]
        }
      },
      {
        "name": "edit",
        "description": "Perform exact string replacements in one governed file inside this member's admitted file root. Paths resolve against that root; escaping targets are refused. old_string must appear verbatim (and uniquely unless replace_all is true); the edit never creates a file.",
        "parameters": {
          "type": "object",
          "properties": {
            "file_path": {
              "type": "string",
              "description": "path relative to the governed root, or an absolute path inside it"
            },
            "old_string": {
              "type": "string",
              "description": "the exact text to replace (non-empty, must appear verbatim)"
            },
            "new_string": {
              "type": "string",
              "description": "the replacement text (empty string deletes)"
            },
            "replace_all": {
              "type": "boolean",
              "description": "replace every occurrence instead of requiring a unique match (default false)"
            }
          },
          "required": [
            "file_path",
            "old_string",
            "new_string"
          ]
        }
      },
      {
        "name": "read_image",
        "description": "Read one governed image file inside this member's admitted file root and attach it to the conversation. Paths resolve against that root; escaping targets are refused. The file is durably committed to the session's attachment store and referenced as an image block.",
        "parameters": {
          "type": "object",
          "properties": {
            "file_path": {
              "type": "string",
              "description": "path relative to the governed root, or an absolute path inside it"
            }
          },
          "required": [
            "file_path"
          ]
        }
      },
      {
        "name": "bash",
        "description": "Run commands in a persistent bash shell. State, including the current directory and exported environment variables, persists across calls for this agent.",
        "parameters": {
          "type": "object",
          "properties": {
            "command": {
              "type": "string",
              "description": "The bash command to run. Relative path is preferred in the command."
            }
          },
          "required": [
            "command"
          ]
        }
      },
      {
        "name": "team_skill",
        "description": "Load the full instructions for a skill, governed: reads only the host-sanctioned skill root(s) this mount configures, resolves the name through the anchor law (no parent segments, no symlink escape), and refuses unknown skills. Call it before acting on a task that names or clearly matches a skill in the session skill catalog.",
        "parameters": {
          "type": "object",
          "properties": {
            "name": {
              "type": "string",
              "description": "The exact skill name from the available skills list."
            }
          },
          "required": [
            "name"
          ],
          "additionalProperties": false
        }
      },
      {
        "name": "team_cordis_inspect_list",
        "description": "List every Cordis Inspect Provider currently known to the Host, governed: the listing is read through the host registry public face after PA admission. Each entry includes its platform, purpose, read-only methods, and input/output schemas. Call this tool before configuring a plugin, then select the provider and method for team_cordis_inspect_query from its result. Do not guess names or treat an Inspect method as a business Service that plugin code can call.",
        "parameters": {
          "type": "object",
          "properties": {},
          "additionalProperties": false
        }
      },
      {
        "name": "team_cordis_inspect_query",
        "description": "Run a read-only query declared by an Inspect Provider, governed: platform, provider, and method must come from team_cordis_inspect_list, and input must satisfy that method's schema (invalid or unverifiable input is refused before dispatch). The query waits under a bounded settle race: on timeout or cancellation the call answers a typed refusal and a late result is NEVER delivered. This tool cannot invoke business Service methods or modify the runtime.",
        "parameters": {
          "type": "object",
          "properties": {
            "platform": {
              "type": "string",
              "enum": [
                "host",
                "client"
              ],
              "description": "Runtime platform that owns the Provider."
            },
            "provider": {
              "type": "string",
              "description": "Exact Provider ID returned by team_cordis_inspect_list."
            },
            "method": {
              "type": "string",
              "description": "Exact method name declared by the Provider manifest."
            },
            "input": {
              "description": "Optional query input; it must satisfy the method input schema. (Any JSON value; a node without `type` is the host subset's unconstrained form.)"
            }
          },
          "required": [
            "platform",
            "provider",
            "method"
          ],
          "additionalProperties": false
        }
      },
      {
        "name": "team_grep",
        "description": "Governed search (a5p5 lane): strict pattern search over the realm; effects derived read-time, admission-gated before any backend runs.",
        "parameters": {
          "type": "object",
          "properties": {
            "pattern": {
              "type": "string"
            },
            "path": {
              "type": "string"
            },
            "glob": {
              "type": "string"
            },
            "output_mode": {
              "type": "string",
              "enum": [
                "content",
                "files_with_matches",
                "count"
              ]
            },
            "fixed_string": {
              "type": "boolean"
            },
            "ignore_case": {
              "type": "boolean"
            },
            "multiline": {
              "type": "boolean"
            },
            "context": {
              "type": "integer",
              "minimum": 0,
              "maximum": 20
            },
            "max_results": {
              "type": "integer",
              "minimum": 1,
              "maximum": 5000
            }
          },
          "required": [
            "pattern"
          ],
          "additionalProperties": false
        }
      },
      {
        "name": "team_glob",
        "description": "Governed filename traversal (a5p5 lane): pattern + target ONLY; admission-gated before any backend runs.",
        "parameters": {
          "type": "object",
          "properties": {
            "pattern": {
              "type": "string"
            },
            "path": {
              "type": "string"
            }
          },
          "required": [
            "pattern"
          ],
          "additionalProperties": false
        }
      },
      {
        "name": "team_bash",
        "description": "Governed shell (a5p5 lane): opaque command text decided by admission + the confined backend; deny-before-backend.",
        "parameters": {
          "type": "object",
          "properties": {
            "command": {
              "type": "string"
            },
            "cwd": {
              "type": "string"
            },
            "timeout": {
              "type": "integer",
              "minimum": 1,
              "maximum": 600000
            },
            "background": {
              "type": "boolean"
            }
          },
          "required": [
            "command"
          ],
          "additionalProperties": false
        }
      },
      {
        "name": "pwsh",
        "description": "Execute a PowerShell command (`pwsh -NoLogo -NoProfile -NonInteractive -Command`) inside this member's admitted working root. Prefer PowerShell syntax (`Get-ChildItem`, `$env:NAME`, backtick continuation); multi-line scripts are supported. The command runs under the mount's confined provider: filesystem writes land only inside the admitted working root. Foreground only — a timed-out command is terminated, never promoted to a background job.",
        "parameters": {
          "type": "object",
          "properties": {
            "command": {
              "type": "string",
              "description": "the PowerShell command text, run as `pwsh -Command <command>` (one argv element — no shell-quoting layer)"
            },
            "description": {
              "type": "string",
              "description": "a short description of what the command does (1 sentence, states why it is needed)"
            },
            "workdir": {
              "type": "string",
              "description": "working directory inside the governed working root (default: the root itself)"
            },
            "timeoutMs": {
              "type": "integer",
              "minimum": 1,
              "description": "kill the command after this many milliseconds (the row terminates a timed-out payload; the exit code is reported as not-observed)"
            }
          },
          "required": [
            "command",
            "description"
          ],
          "additionalProperties": false
        }
      }
    ]
  }
}
